  Object.assign(state,{jMenuLedger:'日常生活',jSyncState:'notConfigured',jTagDraft:null,jTagQuery:'',jTagMany:false});
  dContextKeys.push('jSyncState');
  rSpecs['ledger-actions']={title:'账本操作',host:'ledgers',kind:'dialog'};
  rSpecs['tag-picker-many']={title:'选择标签',host:'editor',kind:'sheet'};
  fDefine('ledger-actions','账本操作菜单','交互补充','main/ledgers_page_new.dart',()=>jLedgerMenu());
  fDefine('tag-picker-many','标签多选 · 大量标签','交互补充','tag/widgets/tag_selector.dart',()=>jTagBody(true));
  function ledgers(){return `${subhead('账本管理','leaf:新建账本','plus')}${menuCard([['leaf:加入共享账本','users-round','加入共享账本','通过邀请链接或邀请码加入']])}${['日常生活','家庭账本'].map((name,index)=>{const selected=name===state.ledger;return `<section class="bc-surface j-ledger-card" data-j-ledger="${name}" data-current="${selected}" aria-label="${name}${selected?'，当前账本':''}"><div class="bc-between">${btn('j-ledger-select:'+name,`<span class="bc-entry-icon warm">${icon(index?'users-round':'book-open')}</span><span><h3>${name}</h3><small>${index?'共享账本 · 2位成员':'个人账本 · 人民币'}</small></span>`,selected?name+'，当前账本':'切换到'+name,'j-ledger-select',`aria-pressed="${selected}"`)}${selected?`<span class="j-current-ledger">${icon('check')}当前账本</span>`:btn('j-ledger-select:'+name,'切换','切换到'+name,'bc-link')}</div><div class="bc-dual j-ledger-totals"><div><label>本月支出</label><strong class="bc-num">¥${money(index?6800.8:3286.5)}</strong></div><div><label>本月收入</label><strong class="bc-num">¥${money(index?24000:12000)}</strong></div></div><div class="j-ledger-actions">${btn('ledger-budget:'+name,`${icon('chart-pie')}预算管理`,name+'预算管理','bc-secondary')}${btn('j-ledger-direct:'+name,`${icon(index?'users-round':'settings-2')}${index?'成员管理':'编辑账本'}`,index?'成员管理':'编辑账本','bc-secondary')}${btn('j-ledger-menu:'+name,icon('ellipsis'),name+'更多操作','j-ledger-more',`aria-haspopup="dialog"`)}</div></section>`;}).join('')}${btn('leaf:新建账本',`${icon('plus')}新建账本`,'新建账本','bc-primary')}`;}
  function jLedgerMenu(){const name=state.jMenuLedger,shared=name==='家庭账本',owner=state.fRole!=='编辑者';return `<div class="j-ledger-context"><span class="bc-entry-icon warm">${icon(shared?'users-round':'book-open')}</span><div><h3>${name}</h3><small>${shared?'共享账本 · '+(owner?'创建者':'可编辑成员'):'本地账本'}</small></div></div><div class="j-ledger-menu">${owner?menuRow('j-ledger-action:edit','pencil','编辑账本'):''}${menuRow('j-ledger-action:budget','chart-pie','预算管理')}${shared?menuRow('j-ledger-action:members','users-round','成员管理')+menuRow('j-ledger-action:stats','chart-no-axes-combined','成员统计'):''}${owner?menuRow('j-ledger-action:clear','list-x','清空账本'):''}${menuRow('j-ledger-action:local','folder-minus','仅删除本地账本')}${owner?menuRow('j-ledger-action:delete','trash-2','删除账本'):''}</div>`;}
  function jOpenLedgerMenu(name){state.jMenuLedger=name;rOpenModal('ledger-actions');}
  function jLedgerAction(action,name=state.jMenuLedger){if(action==='edit'){state.fForm.ledgerName=name;rOpenModal('ledger-edit');}else if(['budget','members','stats'].includes(action)){state.ledger=name;rDismiss();navigate(action==='budget'?'budget':action==='members'?'flow-members':'flow-member-stats');}else{rDismiss();const title=action==='clear'?'清空账本':action==='local'?'仅删除本地账本':'删除账本';sheet(title+'？',`<p class="bc-note">${esc(name)}${action==='local'?'的本地副本将被移除，云端数据保留。':action==='clear'?'中的账单将被清空。':'及关联数据将被删除。'}</p><div class="bc-inline-actions">${btn('close','取消','取消操作','bc-secondary')}${btn('j-ledger-confirm:'+title,'确认'+title,'确认'+title,'bc-primary')}</div>`);}}
  let jLedgerPress=null,jLedgerBlock=0;
  root.addEventListener('pointerdown',e=>{const card=e.target.closest('[data-j-ledger]'),action=e.target.closest('[data-action]')?.dataset.action;if(!card||e.button!==0||action&&!action.startsWith('j-ledger-select:'))return;const g={name:card.dataset.jLedger,x:e.clientX,y:e.clientY,timer:0};g.timer=setTimeout(()=>{if(jLedgerPress===g){jLedgerBlock=performance.now()+1000;jOpenLedgerMenu(g.name);jLedgerPress=null;}},480);jLedgerPress=g;},true);
  root.addEventListener('pointermove',e=>{if(jLedgerPress&&Math.hypot(e.clientX-jLedgerPress.x,e.clientY-jLedgerPress.y)>9){clearTimeout(jLedgerPress.timer);jLedgerPress=null;}},true);
  for(const event of ['pointerup','pointercancel'])root.addEventListener(event,()=>{if(jLedgerPress){clearTimeout(jLedgerPress.timer);jLedgerPress=null;}},true);
  root.addEventListener('contextmenu',e=>{const card=e.target.closest('[data-j-ledger]');if(card){e.preventDefault();jLedgerBlock=performance.now()+800;jOpenLedgerMenu(card.dataset.jLedger);}},true);
  const jSyncStates={
    notConfigured:{label:'未配置云端',detail:'当前为本地模式，账单保存在设备上。',icon:'cloud-off',tone:'muted',action:'配置云服务'},
    notLoggedIn:{label:'未登录',detail:'登录云服务后才能检查并同步此账本。',icon:'log-in',tone:'warning',action:'去登录'},
    noRemote:{label:'云端暂无数据',detail:'云端还没有此账本，可先上传本地数据。',icon:'cloud-upload',tone:'muted',action:'上传到云端'},
    inSync:{label:'已同步',detail:'本地与云端数据一致。',icon:'circle-check',tone:'success',action:'检查更新'},
    localNewer:{label:'本地有更新',detail:'有3项本地变更等待上传。',icon:'cloud-upload',tone:'info',action:'查看同步预览'},
    cloudNewer:{label:'云端有更新',detail:'云端有新记录，建议下载同步。',icon:'cloud-download',tone:'info',action:'查看同步预览'},
    different:{label:'本地与云端有差异，建议下载对比',detail:'本地和云端都发生了变更，请先核对差异。',icon:'git-compare-arrows',tone:'warning',action:'查看差异'},
    error:{label:'状态获取失败',detail:'连接云服务超时，本次检查未完成。你的本地账单仍保留。',icon:'circle-alert',tone:'error',action:'重新检查'},
    loading:{label:'正在检查同步状态…',detail:'正在核对本地与云端数据。',icon:'loader-circle',tone:'muted',action:'正在检查'},
    syncing:{label:'正在同步 · 3 / 8',detail:'正在上传附件，请保持网络连接。',icon:'refresh-cw',tone:'info',action:'同步中'},
    offline:{label:'状态获取失败 · 网络不可用',detail:'暂时无法连接云服务，联网后可重试。本地记账可以继续。',icon:'wifi-off',tone:'warning',action:'重新检查'}
  };
  function jSyncRow(key=state.jSyncState,action='j-sync-detail'){const st=jSyncStates[key]||jSyncStates.error,busy=['loading','syncing'].includes(key);return btn(action,`<span class="bc-menu-symbol">${icon('cloud-sync')}</span><span class="bc-menu-copy"><b>数据同步</b><small data-tone="${st.tone}">${esc(st.label)}</small></span><span class="j-sync-trailing" data-tone="${st.tone}" ${busy?'role="status"':''}>${busy?icon('loader-circle'):key==='inSync'?icon('circle-check'):['error','offline','different'].includes(key)?icon(st.icon):icon('chevron-right')}</span>`,'数据同步，'+st.label,'bc-menu-row j-sync-row',`data-sync-state="${key}" ${key==='notConfigured'&&action==='j-sync-detail'?'disabled':''}`);}
  function mine(){const t=document.createElement('template');t.innerHTML=jPreviousMine();const row=t.content.querySelector('[data-action="leaf:数据同步"]');if(row)row.outerHTML=jSyncRow();return uEnhanceMine(t.innerHTML);}
  const jOriginalSyncBody=fDefs['cloud-sync'].body;
  fDefs['cloud-sync'].body=()=>{const key=state.jSyncState,st=jSyncStates[key]||jSyncStates.error,blocked=['notConfigured','notLoggedIn','error','offline','loading','syncing'].includes(key);return `${surface(`<div class="d-identity j-sync-hero" data-tone="${st.tone}"><span class="bc-entry-icon">${icon(st.icon)}</span><div><h3>${esc(st.label)}</h3><small>${esc(state.ledger)} · ${key==='notConfigured'?'本地模式':'BeeCount Cloud'}</small></div></div><p class="j-sync-explanation">${esc(st.detail)}</p>${key==='syncing'?'<div class="bc-budget-track"><span style="width:37.5%"></span></div>':''}${['error','offline'].includes(key)?'<div class="j-sync-error-detail"><span>本次状态</span><strong>未完成检查</strong><span>错误原因</span><strong>连接超时 / 网络不可用</strong><span>处理方式</span><strong>检查连接后重试，或查看诊断</strong></div>':''}`)}${blocked?fCTA('j-sync-primary',st.action):fCTA('f-go:sync-preview',st.action)}${['error','offline'].includes(key)?menuCard([['f-go:sync-health','heart-pulse','同步健康检查','检查未推送记录与附件'],['f-go:logs','file-text','查看诊断日志','查看本次失败的详细原因'],['f-go:cloud-config','settings-2','检查云服务配置','核对地址与登录状态']]):!blocked?jOriginalSyncBody():''}`;};
  fDefine('sync-states','我的 · 同步状态展示','交互补充','main/mine_page.dart',()=>`${surface(`<h3>原有同步状态</h3><p class="bc-small" style="margin:8px 0">点击一项，在「我的」中查看对应状态。</p>${Object.keys(jSyncStates).map(k=>jSyncRow(k,'j-sync-case:'+k)).join('')}`)}`);
  function jSetSync(key){state.jSyncState=key;state.cloud=key==='notConfigured'?'local':'beecount';}
  function jSyncPrimary(){if(state.jSyncState==='notConfigured')navigate('cloud');else if(state.jSyncState==='notLoggedIn')navigate('flow-login');else if(!['loading','syncing'].includes(state.jSyncState)){jSetSync('loading');render();setTimeout(()=>{jSetSync('inSync');state.fSyncDone=true;render();persist();},700);}}
  function rAfterRender(){jPreviousAfterRender();const brand=document.getElementById('bee-brand-preview');if(brand){brand.value=settings.showBrand?'shown':'hidden';brand.parentElement.hidden=state.page!=='home';}const manyOption=picker.querySelector('option[value="flow-tag-picker-many"]');if(manyOption)manyOption.textContent='标签多选 · 大量标签';const control=document.getElementById('bee-sync-preview-control'),select=document.getElementById('bee-sync-preview');if(control){control.hidden=!['mine','flow-cloud-sync','flow-sync-states'].includes(state.page);if(!select.options.length)select.innerHTML=Object.entries(jSyncStates).map(([v,s])=>`<option value="${v}">${s.label}</option>`).join('');select.value=state.jSyncState;}}
  const jExtraTags=['早餐','午餐','晚餐','咖啡','通勤','购物','数码','健康','运动','教育','宠物','礼物','住房','订阅','交通','现金','报销','亲友','周末','出差','计划内','临时','房租','水电'];
  function jTagChoices(tags){return tags.map(n=>bcTagChoice(n,state.jTagDraft.includes(n))).join('');}
  function jTagBody(many=false){
    if(!state.jTagDraft){state.jTagDraft=state.recordTags?.length?[...state.recordTags]:state.tag?[state.tag]:[];state.jTagQuery='';}
    state.jTagMany=many;const tags=[...new Set([...Object.keys(tagColors),...(many?jExtraTags:[])])],filtered=tags.filter(n=>n.toLowerCase().includes(state.jTagQuery.trim().toLowerCase())),recent=['工作日','日常','旅行'].filter(n=>tags.includes(n));
    return `<label class="p-search-box j-tag-search">${icon('search')}<input data-j-tag-query value="${esc(state.jTagQuery)}" placeholder="搜索标签" aria-label="搜索标签"></label><div class="j-tag-summary"><span>可选择多个标签</span><span>已选 ${state.jTagDraft.length} 个</span></div><div class="j-tag-groups">${!state.jTagQuery.trim()&&recent.length?`<h4>最近使用</h4><div class="j-tag-cloud" role="group" aria-label="最近使用标签">${jTagChoices(recent)}</div>`:''}<h4>全部标签</h4><div class="j-tag-cloud" role="group" aria-label="标签多选">${jTagChoices(filtered)||'<p class="bc-small">没有找到这个标签</p>'}</div></div><div class="j-picker-actions">${btn('j-tags-clear','清空选择','清空已选标签','bc-secondary')}${btn('j-tags-confirm',`使用所选标签${state.jTagDraft.length?'（'+state.jTagDraft.length+'）':''}`,'使用所选标签','bc-primary')}</div><div class="j-new-tag">${menuRow('f-go:tag-edit','plus','新建标签')}</div>`;
  }

  root.addEventListener('input',e=>{if(e.target.matches('[data-j-tag-query]')){const pos=e.target.selectionStart;state.jTagQuery=e.target.value;rBuildModal();const input=phone.querySelector('[data-j-tag-query]');input.focus({preventScroll:true});input.setSelectionRange(pos,pos);}});
  root.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const [action,...parts]=el.dataset.action.split(':'),arg=parts.join(':');if(!action.startsWith('j-ledger-')&&!action.startsWith('j-sync-')&&!action.startsWith('j-tag')&&!action.startsWith('j-tags-'))return;e.preventDefault();e.stopImmediatePropagation();
    if(action==='j-ledger-select'){if(performance.now()<jLedgerBlock)return;state.ledger=arg;render();}
    else if(action==='j-ledger-menu')jOpenLedgerMenu(arg);
    else if(action==='j-ledger-direct'){state.jMenuLedger=arg;jLedgerAction(arg==='家庭账本'?'members':'edit',arg);}
    else if(action==='j-ledger-action')jLedgerAction(arg);
    else if(action==='j-ledger-confirm'){closeSheet();notice(arg+'完成');}
    else if(action==='j-sync-detail')navigate('flow-cloud-sync');
    else if(action==='j-sync-case'){jSetSync(arg);navigate('mine');}
    else if(action==='j-sync-primary')jSyncPrimary();
    else if(action==='j-tag-toggle'){const i=state.jTagDraft.indexOf(arg);if(i>=0)state.jTagDraft.splice(i,1);else state.jTagDraft.push(arg);rBuildModal();}
    else if(action==='j-tags-clear'){state.jTagDraft=[];rBuildModal();}
    else if(action==='j-tags-confirm'){state.recordTags=[...state.jTagDraft];state.tag=state.recordTags[0]||'';rDismiss();render();}
    persist();
  },true);
  document.getElementById('bee-sync-preview').addEventListener('change',e=>{jSetSync(e.target.value);render();persist();});
  window.addEventListener('click',e=>{if(e.target.closest('[data-action="f-sync-confirm"]'))jSetSync('inSync');},true);

  document.getElementById('bee-brand-preview').addEventListener('change',e=>{settings.showBrand=e.target.value==='shown';render();persist();});
